<?php if($financeOrAdmin&&(string)$point['status']==='stopped'):?><script>document.getElementById('createDgSignatureLink')?.addEventListener('click',async function(){this.disabled=true;try{const body=new URLSearchParams({_csrf:<?=json_encode((string)$_SESSION['daily_point_csrf'])?>,action:'signature_link',point_id:<?=json_encode((int)$point['id'])?>}),response=await fetch('request/daily_point_action.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body}),data=await response.json();if(!response.ok||!data.ok||!data.signature_url)throw new Error(data.error||'Lien indisponible');const modal=document.createElement('div');modal.className='fixed inset-0 z-[200] grid place-items-center bg-slate-950/75 p-4';modal.innerHTML=`<section class="w-full max-w-xl rounded-lg bg-white p-6 shadow-2xl"><p class="text-xs font-black uppercase text-violet-700">Signature du point #<?= (int)$point['id'] ?></p><h2 class="mt-1 text-2xl font-black">Lien sécurisé du DG</h2><p class="mt-2 text-sm text-slate-600">Ce nouveau lien remplace tout lien créé précédemment.</p><input readonly data-url class="mt-4 w-full rounded-md border bg-slate-50 p-3 text-sm" value="${data.signature_url.replace(/&/g,'&amp;').replace(/"/g,'&quot;')}"><div class="mt-3 flex gap-2"><button type="button" data-copy class="flex-1 rounded-md bg-violet-700 px-4 py-3 font-bold text-white">Copier le lien</button><button type="button" data-close class="rounded-md border px-4 py-3 font-bold">Fermer</button></div></section>`;document.body.appendChild(modal);const input=modal.querySelector('[data-url]');modal.querySelector('[data-copy]').onclick=async e=>{try{await navigator.clipboard.writeText(input.value)}catch(x){input.select();document.execCommand('copy')}e.currentTarget.textContent='Lien copié'};modal.querySelector('[data-close]').onclick=()=>modal.remove();}catch(error){alert(error.message);this.disabled=false;}});</script><?php endif;?>
<script>(()=>{const canvas=document.getElementById('signatureCanvas'),form=document.getElementById('signForm');if(!canvas||!form)return;const ctx=canvas.getContext('2d');ctx.lineWidth=2.5;ctx.lineCap='round';let drawing=false;const pos=e=>{const r=canvas.getBoundingClientRect(),p=e.touches?.[0]||e;return{x:(p.clientX-r.left)*canvas.width/r.width,y:(p.clientY-r.top)*canvas.height/r.height}};const start=e=>{drawing=true;const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);e.preventDefault()};const move=e=>{if(!drawing)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();e.preventDefault()};['mousedown','touchstart'].forEach(x=>canvas.addEventListener(x,start));['mousemove','touchmove'].forEach(x=>canvas.addEventListener(x,move));['mouseup','mouseleave','touchend'].forEach(x=>canvas.addEventListener(x,()=>drawing=false));document.getElementById('clearSignature').onclick=()=>ctx.clearRect(0,0,canvas.width,canvas.height);form.addEventListener('submit',e=>{document.getElementById('signatureData').value=canvas.toDataURL('image/png');});})();</script>
<?php if($myAuth&&$profileSignature!==''):?><script>(()=>{const form=document.getElementById('signForm');if(!form)return;const button=document.createElement('button');button.type='button';button.className='rounded-xl border border-cyan-300 bg-white px-4 py-2 font-bold text-cyan-800';button.textContent='Utiliser ma signature du profil';button.onclick=async()=>{button.disabled=true;try{await window.FineaPasskey.confirmSignature();const f=document.createElement('form');f.method='post';f.action='request/daily_point_profile_sign.php';f.innerHTML=`<input type="hidden" name="_csrf" value="<?= htmlspecialchars((string)$_SESSION['daily_point_page_csrf']) ?>"><input type="hidden" name="id" value="<?= (int)$point['id'] ?>">`;document.body.appendChild(f);f.submit();}catch(error){alert(error.message);button.disabled=false;}};form.querySelector('.mt-3.flex')?.prepend(button);})();</script><?php endif;?>
